"use client";
import { setSystemControl } from "@/lib/admin/actions";
import { MutationForm, ReasonSelect } from "./mutation-form";
import { Button } from "@/components/ui/button";
export function SendingControls({
  sendingEnabled,
  updatedAt,
}: {
  sendingEnabled: boolean;
  updatedAt: string;
}) {
  return (
    <MutationForm
      submit={(data, requestId) =>
        data.get("confirmation") === "on"
          ? setSystemControl({
              sendingEnabled: !sendingEnabled,
              expectedUpdatedAt: updatedAt,
              reasonCode: data.get("reasonCode"),
              requestId,
            })
          : Promise.resolve({ ok: false, code: "INVALID_INPUT" })
      }
    >
      <ReasonSelect />
      <label className="flex items-start gap-2">
        <input name="confirmation" type="checkbox" required className="mt-1" />I
        confirm I want to {sendingEnabled ? "disable" : "enable"} sending for
        all users. A committed Gmail claim cannot be recalled.
      </label>
      <Button variant={sendingEnabled ? "destructive" : "default"}>
        {sendingEnabled ? "Disable all sending" : "Enable sending"}
      </Button>
    </MutationForm>
  );
}
